// Lab 22.2 (milestone M8): the model, the state of a batch of sequences, and the pieces
// you call. Provided; you do not edit this file.
//
// The model is the part of a decoder that every sequence shares (its weights), cut down
// to what batching changes:
//
//   embed       H[r][j] = E[tokens[r]][j]                       (yours)
//   per layer   T = H W_l^T,  T += b_l,  H += T                  (the linear layer, M0, M0)
//   LM head     logits = H E^T                                   (E is tied to the LM head)
//   sampler     probs = softmax(logits / temperature),  tokens = argmax(logits)   (M4)
//
// There is no attention in this step: chapter 20 builds it (M6, M7), and it does not
// batch, because each sequence has its own keys and values (notes/today/ch22-facts.md A6).
// Everything is row-major float32, batch first, as every milestone of the project.
#pragma once
#include <cstdint>

// The project's linear layer, the signature of lab 6.4 (M2), lab 15.6 (M3) and lab 22.1's
// gather: Y[batch x out] = X[batch x in] * W^T, with W stored (out, in) row-major, as
// nn.Linear and ggml store a weight. Device pointers; it launches and does not wait.
typedef void (*LinearFn)(const float* X, const float* W, float* Y, int batch, int in, int out);

#if !defined(__OBJC__)
// ---------------------------------------------------------------- CUDA, HIP, emulators

struct DecodeModel {
    int d;                    // hidden size
    int vocab;                // vocabulary size
    int layers;               // number of (linear, bias, residual) blocks
    const float* E;           // [vocab x d] embedding table, also the LM head's weight
    const float* const* W;    // W[l], l < layers: device pointer to a [d x d] weight, (out, in)
    const float* const* b;    // b[l]: device pointer to a [d] bias
    LinearFn linear;          // which GEMM the step uses: the driver sets it
};

struct DecodeState {
    int batch;                // sequences decoded together
    float temperature;        // softmax scale is 1 / temperature
    int* tokens;              // [batch] the current tokens; the step overwrites them with the next
    float* H;                 // [batch x d] hidden state
    float* T;                 // [batch x d] the output of a layer's linear part
    float* logits;            // [batch x vocab]
    float* probs;             // [batch x vocab]
};

// ---- yours, in <variant>/kernel.cu ----
// H[r][j] = E[tokens[r]][j] for r < batch, j < d. Device pointers.
void launchEmbed(const float* E, const int* tokens, float* H, int batch, int d);
// One greedy decode step for s.batch sequences: one launch per operation for the whole
// batch, nothing waiting inside.
void launchDecodeStep(const DecodeModel& m, DecodeState& s);

// ---- provided: reference solutions of earlier labs, built beside yours ----
// Lab 2.3 (M0). Y[r][j] = X[r][j] + bias[j]; Y may be X. And X[i] += R[i] for i < n.
void launchAddBias(float* Y, const float* X, const float* bias, int rows, int d);
void launchAddResidual(float* X, const float* R, int n);
// Lab 10.3 (M4). One block of 256 threads per row.
// y[r] = softmax(scale * x[r]); idx[r] = the lowest c with x[r][c] equal to the row's maximum.
void launchSoftmaxRows(const float* x, float* y, int rows, int cols, float scale);
void launchArgmaxRows(const float* x, int* idx, int rows, int cols);

#else
// ---------------------------------------------------------------- Metal
#import <Foundation/Foundation.h>
#import <Metal/Metal.h>

// The Metal counterpart of LinearFn: one dispatch (or more) into an open compute encoder,
// with the pipeline that encoder function expects.
typedef void (*EncodeLinearFn)(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                               id<MTLBuffer> X, id<MTLBuffer> W, id<MTLBuffer> Y,
                               uint32_t batch, uint32_t in, uint32_t out);

// Compiled by the driver, each from its own lab's kernel.metal with the constants that
// lab's driver uses.
struct DecodePipelines {
    id<MTLComputePipelineState> embed;        // embed_rows, from your kernel.metal
    id<MTLComputePipelineState> linear;       // the pipeline encodeLinear expects
    id<MTLComputePipelineState> addBias;      // lab 2.3's add_bias
    id<MTLComputePipelineState> addResidual;  // lab 2.3's add_residual
    id<MTLComputePipelineState> softmax;      // lab 10.3's softmax_rows
    id<MTLComputePipelineState> argmax;       // lab 10.3's argmax_rows
};

struct DecodeModel {
    uint32_t d, vocab, layers;
    id<MTLBuffer> E;                  // [vocab x d], also the LM head's weight
    NSArray<id<MTLBuffer>>* W;        // W[l]: [d x d], (out, in)
    NSArray<id<MTLBuffer>>* b;        // b[l]: [d]
    EncodeLinearFn encodeLinear;      // which GEMM the step uses: the driver sets it
    DecodePipelines pipelines;
};

struct DecodeState {
    uint32_t batch;
    float temperature;
    id<MTLBuffer> tokens;             // [batch] int32; the step overwrites them with the next
    id<MTLBuffer> H, T;               // [batch x d]
    id<MTLBuffer> logits, probs;      // [batch x vocab]
};

// ---- yours, in <variant>/launch.mm (embed_rows is in <variant>/kernel.metal) ----
void encodeEmbed(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                 id<MTLBuffer> E, id<MTLBuffer> tokens, id<MTLBuffer> H, uint32_t batch, uint32_t d);
// Encodes one greedy decode step into `enc`, which the caller opened (a serial encoder)
// and will end, commit and wait for. Returns false if a piece refused to dispatch.
bool encodeDecodeStep(id<MTLComputeCommandEncoder> enc, const DecodeModel& m, DecodeState& s);

// ---- provided: reference solutions of earlier labs ----
// Lab 2.3 (M0). Y may be X.
void encodeAddBias(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                   id<MTLBuffer> Y, id<MTLBuffer> X, id<MTLBuffer> bias, uint32_t rows, uint32_t d);
void encodeAddResidual(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                       id<MTLBuffer> X, id<MTLBuffer> R, uint32_t n);
// Lab 10.3 (M4). Each returns false, without dispatching, if the pipeline cannot run
// 256 threads per threadgroup in whole SIMD-groups.
bool encodeSoftmaxRows(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                       id<MTLBuffer> x, id<MTLBuffer> y, uint32_t rows, uint32_t cols, float scale);
bool encodeArgmaxRows(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                      id<MTLBuffer> x, id<MTLBuffer> idx, uint32_t rows, uint32_t cols);
#endif
